// Este no recebe as varias ramificacoes do Switch, por isso corre uma vez por
// evento. Como calcula sempre a partir do array completo de eventos do trigger,
// as corridas seguintes dao exactamente o mesmo resultado e so repetiam o PATCH
// no Airtable (~0,5s cada). Uma escrita por commit chega.
if ($runIndex > 0) return [];

// Calcular update da Lead — ver §6.5 da ESPECIFICAÇÃO
const eventos = $('Execute Workflow Trigger').first().json.eventos || [];
let leadIdFromCreate = null;
try { leadIdFromCreate = $('Criar LEAD (nova)').first().json.id; } catch (e) {}
const leadId = $('Execute Workflow Trigger').first().json._contexto_n8n.lead_id || leadIdFromCreate;

// ultima_nota = nota_ficheiro do último evento de categoria 'nota'
const notas = eventos.filter(e => e.categoria === 'nota');
const ultimaNota = notas.length ? notas[notas.length - 1].nota_ficheiro : undefined;

// mudança de estágio (se existir)
const mudancas = eventos.filter(e => e.tipo === 'mudanca_estagio');
const mudanca = mudancas.length ? mudancas[mudancas.length - 1] : null;

const fields = { id: leadId };

if (ultimaNota !== undefined && ultimaNota !== null) {
  fields.ultima_nota = ultimaNota;
}

if (mudanca) {
  const subtipo = mudanca.dados ? mudanca.dados.subtipo : undefined;
  if (subtipo === 'nutricao') {
    fields.estagio = 'nutricao';
    fields.fase_origem = mudanca.dados.fase_origem;
    fields.motivo_saida = mudanca.dados.motivo;
    fields.motivo_livre = mudanca.dados.motivo_livre;
    fields.desfecho_proposto = mudanca.dados.desfecho_proposto;
    fields.data_dita = mudanca.dados.data_dita;
    fields.Status = 'em_triagem';
  } else {
    // avanço / recuo
    fields.estagio = mudanca.dados.estagio_destino;
  }
} else {
  fields.Status = 'ativa';
}

// banco_proposta (§4.10 do prompt) — merge, nunca overwrite cego: le o que ja
// estava (Get Lead Atual, antes do Split eventos) e so mexe no(s) banco(s)
// que este commit mencionou.
const bancoEventos = eventos.filter(e => e.tipo === 'banco_proposta' && e.dados && e.dados.banco && e.dados.estado_proposta);
if (bancoEventos.length) {
  let atual = [];
  try {
    const leadAtual = $('Get Lead Atual').first().json;
    const fAtual = leadAtual.fields || leadAtual;
    const raw = fAtual.propostas_banco;
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (Array.isArray(parsed)) atual = parsed;
  } catch (e) {}
  const porNome = new Map(atual.map(p => [String(p.banco || '').toLowerCase(), { ...p }]));
  for (const ev of bancoEventos) {
    porNome.set(ev.dados.banco.toLowerCase(), { banco: ev.dados.banco, estado: ev.dados.estado_proposta });
  }
  fields.propostas_banco = JSON.stringify(Array.from(porNome.values()));
}

// checklist_documento (§4.14) — merge por item, mesmo padrao do banco_proposta.
const checklistEventos = eventos.filter(e => e.tipo === 'checklist_documento' && e.dados && e.dados.item && e.dados.estado_checklist);
if (checklistEventos.length) {
  let atual = [];
  try {
    const leadAtual = $('Get Lead Atual').first().json;
    const fAtual = leadAtual.fields || leadAtual;
    const raw = fAtual.checklist_documentos;
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (Array.isArray(parsed)) atual = parsed;
  } catch (e) {}
  const porItem = new Map(atual.map(it => [String(it.item || '').toLowerCase(), { ...it }]));
  for (const ev of checklistEventos) {
    const existente = porItem.get(ev.dados.item.toLowerCase()) || {};
    porItem.set(ev.dados.item.toLowerCase(), { ...existente, item: ev.dados.item, estado: ev.dados.estado_checklist });
  }
  fields.checklist_documentos = JSON.stringify(Array.from(porItem.values()));
}

// dados_lead (§4.13) — correcao directa; so entram os campos que vieram preenchidos.
const dadosLeadEventos = eventos.filter(e => e.tipo === 'dados_lead');
if (dadosLeadEventos.length) {
  const ev = dadosLeadEventos[dadosLeadEventos.length - 1];
  const dl = ev.dados || {};
  if (dl.telefone) fields.Telefone = dl.telefone;
  if (dl.origem_lead) fields.origem_lead = dl.origem_lead;
  if (dl.tipo_lead) fields.tipo = dl.tipo_lead;
  if (dl.valor) fields.Valor = Number(dl.valor) || dl.valor;
}

return [{ json: fields }];

// PREPARAR LEAD NOVA — identifica pessoas novas (sem lead_id) no lote
// e produz um item por pessoa distinta, para o Airtable criar uma Lead por item.
// IMPORTANTE: os nomes dos campos abaixo têm de ser IGUAIS aos nomes das colunas
// no Airtable, porque o node "Criar LEAD (nova)" usa o modo "Map Automatically".
const eventos = $json.eventos || [];
const ctx = $('Execute Workflow Trigger').first().json._contexto_n8n || {};

const novos = eventos.filter(e => e.ancora && e.ancora.estado === 'nova' && !e.ancora.lead_id);

const grupos = new Map();
for (const e of novos) {
  const telefoneEv = e.ancora.telefone || (e.dados && e.dados.telefone) || '';
  const chave = (e.ancora.nome_exibicao || '') + '|' + telefoneEv;
  if (!grupos.has(chave)) {
    const item = {
      Nome: e.ancora.nome_exibicao || (e.dados && e.dados.nome) || '',
      Telefone: telefoneEv,
      Comercial: ctx.comercial_id ? [ctx.comercial_id] : [],
      estagio: 'lead',
      Status: 'ativa',
    };
    const origem = (e.dados && e.dados.origem_lead) || null;
    if (origem) item.origem_lead = origem;
    grupos.set(chave, item);
  }
}

return [...grupos.values()].map(g => ({ json: g }));

// APLICAR LEAD NOVA — junta o id da(s) Lead(s) recem-criada(s) de volta aos eventos,
// casando por Nome+Telefone normalizados.
// A resposta do Airtable traz os campos dentro de .fields, e numa lead nova
// o nome vem em nome_dito (nome_exibicao ainda e null).
const eventos = $('Edit Fields').first().json.eventos || [];
const criadas = $input.all().map(i => i.json);

const norm = (v) => String(v == null ? '' : v).toLowerCase().replace(/\s+/g, ' ').trim();
const normTel = (v) => String(v == null ? '' : v).replace(/\D/g, '');
const chave = (nome, telefone) => norm(nome) + '|' + normTel(telefone);

const porChave = new Map();
for (const c of criadas) {
  const f = c.fields || c;
  porChave.set(chave(f.Nome, f.Telefone), c.id);
}

const idUnico = criadas.length === 1 ? criadas[0].id : null;

const eventosAtualizados = eventos.map((e) => {
  if (e.ancora && e.ancora.estado === 'nova' && !e.ancora.lead_id) {
    const telEv = e.ancora.telefone || (e.dados && e.dados.telefone) || '';
    const nomeEv = e.ancora.nome_exibicao || e.ancora.nome_dito || (e.dados && e.dados.nome) || '';
    const leadId = porChave.get(chave(nomeEv, telEv)) || idUnico;
    if (leadId) {
      return { ...e, ancora: { ...e.ancora, lead_id: leadId, nome_exibicao: e.ancora.nome_exibicao || nomeEv, estado: 'resolvida' } };
    }
  }
  return e;
});

return [{ json: { eventos: eventosAtualizados } }];
